import{_ as e,r as s,o,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"字段依赖 - October CMS - 3.x","titleTemplate":false,"description":"了解字段如何依赖于其他字段。","frontmatter":{"subtitle":"了解字段如何依赖于其他字段。"},"headers":[{"level":2,"title":"过滤字段","slug":"过滤字段","link":"#过滤字段","children":[]},{"level":2,"title":"使用 AJAX 更新","slug":"使用-ajax-更新","link":"#使用-ajax-更新","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/extend/forms/field-dependencies.md","filePath":"3.x/zh-cn/extend/forms/field-dependencies.md"}'),i={name:"3.x/zh-cn/extend/forms/field-dependencies.md"};function u(k,n,d,g,y,f){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"字段依赖",-1)),a(p),n[1]||(n[1]=r(`<p>类似于<a href="./../../element/form-fields.html">表单字段条件</a>，表单字段可以通过定义 <code>dependsOn</code> 表单字段属性来声明对其他字段的依赖关系。这提供了一种更强大的服务端解决方案，当依赖项被修改时更新字段。</p><p>当声明为依赖项的字段发生更改时，定义字段将使用 AJAX 框架进行更新。这提供了使用 <code>filterFields</code> 方法与字段属性交互或更改提供给字段的可用选项的机会。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">country</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown

<span class="token key atrule">state</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> State
    <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
</code></pre></div><p>在上面的示例中，当 <code>country</code> 字段的值发生更改时，<code>state</code> 表单字段将刷新。此时，当前表单数据将填充到模型中，以便下拉选项可以使用它。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCountryOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;au&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Australia&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ca&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Canada&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getStateOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">country</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;au&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;act&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Capital Territory&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;qld&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Queensland&#39;</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">elseif</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">country</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;ca&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;bc&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;British Columbia&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;on&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Ontario&#39;</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="过滤字段"><a href="#过滤字段" class="header-anchor">#</a> 过滤字段</h2><p>您可以通过在所使用的模型中覆盖 <code>filterFields</code> 方法来过滤表单字段定义。这允许您根据模型数据操纵字段的可见性和其他属性。该方法接受两个参数：<strong>$fields</strong> 代表已由<a href="./../../element/form-fields.html">字段配置</a>定义的字段对象，<strong>$context</strong> 代表当前活动的表单上下文。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">filterFields</span><span class="token punctuation">(</span><span class="token variable">$fields</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">source_type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;http&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
        <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">elseif</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">source_type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;git&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
        <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">else</span> <span class="token punctuation">{</span>
        <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
        <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在显示和保存表单时，<code>$context</code> 值将包含表单上下文（create、update 等），但是当表单被刷新时，上下文将始终设置为 <strong>refresh</strong>。这对于用新值填充字段而不强制其成为保存值非常有用。以下示例将在刷新期间父值更改时重置父名称值，但不会影响保存值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">filterFields</span><span class="token punctuation">(</span><span class="token variable">$fields</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$context</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;refresh&#39;</span> <span class="token operator">&amp;&amp;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">parent</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">parent_name</span><span class="token operator">-&gt;</span><span class="token property">value</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">parent</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>上述逻辑将通过检查模型属性 <code>source_type</code> 的值来设置某些字段的 <code>hidden</code> 标志。此逻辑将在表单首次加载时以及由已定义的字段依赖项更新时应用。例如，以下是关联的表单字段定义。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">source_type</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Source Type
    <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
    <span class="token key atrule">options</span><span class="token punctuation">:</span>
        <span class="token key atrule">git</span><span class="token punctuation">:</span> Git
        <span class="token key atrule">http</span><span class="token punctuation">:</span> Http
        <span class="token key atrule">upload</span><span class="token punctuation">:</span> Upload

<span class="token key atrule">source_url</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Source URL
    <span class="token key atrule">type</span><span class="token punctuation">:</span> text
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> source_type

<span class="token key atrule">git_branch</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Git Branch
    <span class="token key atrule">type</span><span class="token punctuation">:</span> text
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> source_type
</code></pre></div><h2 id="使用-ajax-更新"><a href="#使用-ajax-更新" class="header-anchor">#</a> 使用 AJAX 更新</h2><p>在某些情况下，您可能希望在字段值更改时手动运行 AJAX 处理程序。您可以使用 <code>changeHandler</code> 属性指定 AJAX 处理程序。以下示例将在值更改时调用 <strong>onChangeContent</strong> AJAX 处理程序。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
    <span class="token key atrule">changeHandler</span><span class="token punctuation">:</span> onChangeContent
</code></pre></div><p>可以按常规方式将 AJAX 处理程序添加到控制器中。以下示例在字段更新时使用 <code>Flash</code> facade 显示一条消息。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onChangeContent</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Great job!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果您希望更新其他字段，请使用表单控制器提供的 <code>formRefreshFields</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onChangeContent</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRefreshFields</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_positive&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您也可以通过传递数组一次更新多个字段。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onChangeContent</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRefreshFields</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;is_positive&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;internal_comments&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../../element/form-fields.html">表单字段条件</a></li></ul></div>`,23))])}const v=e(i,[["render",u]]);export{b as __pageData,v as default};
